<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();$q=[];foreach(['patients','visits','appointments','admissions','lab_orders','invoices','contact_messages'] as $t){$q[$t]=(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();}$q['open_admissions']=(int)$pdo->query("SELECT COUNT(*) FROM admissions WHERE status='Admitted'")->fetchColumn();$q['unpaid']=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM invoices WHERE status IN ('Unpaid','Part-paid')")->fetchColumn();admin_header('Dashboard','index.php');?><div class="pagehead"><div><h1>Hospital Dashboard</h1><div class="muted">Welcome, <?=e($_SESSION['admin_name']??'Administrator')?>.</div></div></div><div class="grid"><?php $labels=['patients'=>'Patients','visits'=>'Visits','appointments'=>'Appointments','admissions'=>'Admissions','lab_orders'=>'Lab Orders','invoices'=>'Invoices','contact_messages'=>'Messages','open_admissions'=>'Currently Admitted'];foreach($labels as $k=>$v):?><div class="card stat"><span class="muted"><?=e($v)?></span><span class="n"><?=$q[$k]?></span></div><?php endforeach;?></div><div class="grid" style="margin-top:18px"><div class="card"><h2>Outstanding billing</h2><div class="n" style="font-size:26px">UGX <?=number_format($q['unpaid'],0)?></div><a class="btn" href="billing.php">Open billing</a></div><div class="card"><h2>Quick registration</h2><a class="btn" href="patients.php?action=new">Register patient</a> <a class="btn secondary" href="visits.php?action=new">Record visit</a> <a class="btn secondary" href="admissions.php?action=new">Admit patient</a></div></div><?php admin_footer();
